fn find(names: &str, ends: &[u16], codes: &[u16], name: &str) -> Option<u16> {
    let entry = |index: usize| {
        let start = if index == 0 { 0 } else { ends[index - 1] as usize };
        &names[start..ends[index] as usize]
    };
    let (mut low, mut high) = (0, ends.len());
    while low < high {
        let middle = (low + high) / 2;
        match entry(middle).cmp(name) {
            std::cmp::Ordering::Less => low = middle + 1,
            std::cmp::Ordering::Greater => high = middle,
            std::cmp::Ordering::Equal => return Some(codes[middle]),
        }
    }
    None
}

